 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    objects = []
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in unseen:
                        unseen.remove(p); comp.add(p); stack.append(p)
        if len(comp) == 4:
            rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
            cr, cc = (min(rs) + max(rs)) // 2, (min(cs) + max(cs)) // 2
            if comp == {(cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)}:
                objects.append((cr, cc))
    # Join facing diamond tips when their centers share a row or column.
    for i, (r1,c1) in enumerate(objects):
        for r2,c2 in objects[i+1:]:
            if r1 == r2 and c1 != c2:
